COULOMB WAVE FUNCTIONS (p.542)
14.6. Special Values and Asymptotic Behavior
14.6.1  L>0,\ \rho=0:\ F_L=0,\ F_L'=0,\ G_L=\infty,\ G_L'=-\infty
14.6.2  L=0,\ \rho=0:\ F_0=0,\ F_0'=C_0(\eta),\ G_0=1/C_0(\eta),\ G_0'=-\infty
14.6.3  L\to\infty:\ F_L\sim C_L(\eta)\rho^{L+1},\ G_L\sim D_L(\eta)\rho^{-L}
14.6.4  L=0,\ \eta=0:\ F_0=\sin\rho,\ F_0'=\cos\rho,\ G_0=\cos\rho,\ G_0'=-\sin\rho
14.6.5  \rho\to\infty:\ G_L+iF_L\sim\exp\,i[\rho-\eta\ln2\rho-\tfrac{L\pi}{2}+\sigma_L]
14.6.6  L\ge0,\ \eta=0:\ F_L=(\tfrac12\pi\rho)^{1/2}J_{L+\frac12}(\rho),\ G_L=(-1)^L(\tfrac12\pi\rho)^{1/2}J_{-(L+\frac12)}(\rho)
14.6.7  L\ge0,\ 2\eta>>\rho:\ F_L\sim\frac{(2L+1)!C_L(\eta)}{(2\eta)^{L+1}}(2\eta\rho)^{1/2}I_{2L+1}[2(2\eta\rho)^{1/2}],\ G_L\sim\frac{2(2\eta)^L}{(2L+1)!C_L(\eta)}(2\eta\rho)^{1/2}K_{2L+1}[2(2\eta\rho)^{1/2}]
14.6.8  L=0,\ 2\eta>>\rho:\ F_0\sim e^{-\pi\eta}(\pi\rho)^{1/2}I_1[2(2\eta\rho)^{1/2}],\ F_0'\sim e^{-\pi\eta}(2\pi\eta)^{1/2}I_0[2(2\eta\rho)^{1/2}],\ G_0\sim2e^{\pi\eta}(\rho/\pi)^{1/2}K_1[2(2\eta\rho)^{1/2}],\ G_0'\sim-2(2\eta/\pi)^{1/2}e^{\pi\eta}K_0[2(2\eta\rho)^{1/2}]
14.6.9  L=0,\ 2\eta>>\rho:\ F_0\sim\tfrac12\beta e^\alpha,\ F_0'\sim\tfrac12\beta^{-1}e^\alpha,\ G_0\sim\beta e^{-\alpha},\ G_0'\sim-\beta^{-1}e^{-\alpha},\ \alpha=2\sqrt{2\eta\rho}-\pi\eta,\ \beta=(\rho/2\eta)^{1/2}
14.6.10  L=0,\ 2\eta>>\rho:\ F_0\sim\tfrac12\beta e^\alpha;\ F_0'\sim\{\beta^{-2}+\tfrac1{8\eta}t^{-2}\beta^4\}F_0;\ G_0\sim\beta e^{-\alpha};\ G_0'\sim\{-\beta^{-2}+\tfrac1{8\eta}t^{-2}\beta^4\}G_0,\ t=\rho/2\eta,\ \alpha=2\eta\{[t(1-t)]^{1/2}+\arcsin t^{1/2}-\tfrac12\pi\},\ \beta=\{t/(1-t)\}^{1/2}
14.6.11  L=0,\ \rho>>2\eta:\ F_0=\alpha\sin\beta;\ F_0'=-t^2(bF_0-aG_0);\ G_0=\alpha\cos\beta;\ G_0'=-t^2(aF_0+bG_0),\ t=2\eta/\rho
14.6.12  \eta>>0,\ 2\eta\sim\rho:\ F_L(\eta,\rho)/G_L(\eta,\rho)\sim\sqrt\pi\,\{\rho_L/[1+L(L+1)/\rho_L^2]\}^{1/6}\{\mathrm{Ai}(x)/\mathrm{Bi}(x)\},\ \rho_L=\eta+[\eta^2+L(L+1)]^{1/2}
14.6.13  \eta>>0,\ 2\eta\sim\rho:\ x=(2\eta-\rho)(2\eta)^{-1/3},\ [G_0+iF_0]\sim\pi^{1/2}(2\eta)^{1/6}[\mathrm{Bi}(x)+i\mathrm{Ai}(x)]
14.6.14  \eta>>0:\ \rho_L=\eta+[\eta^2+L(L+1)]^{1/2},\ F_L(\rho_L)/[G_L(\rho_L)/\sqrt3]\sim\tfrac{\Gamma(1/3)}{2\sqrt\pi}(\rho_L/3)^{1/6}\{1+L(L+1)/\rho_L^2\}^{-1/6}
